/**
 * ISO-14046 regulation-table seed builders (Plan 3 Task 26, 2026-09-18).
 *
 * SR-1: every seeded value and every `verbatim_quote` was read in this session
 * from the SPANISH markdown transcript
 * `Desktop\Guidelines\DWA DIN Scribd\ISO-14046\ISO-14046.md` (1096 lines; NTC-ISO
 * 14046 — the Colombian IDT adoption by translation of ISO 14046:2014). The spans
 * live in `regulation-tables-quotes-iso14046.ts` (generated by line range, never
 * retyped); the line range is in each span's name. A markdown transcript is the
 * SR-1 source per owner ruling 2026-09-05 (VC grade) — a table whose every row
 * quote is lifted AND whose every displayed cell is legible ships
 * `verification_status: 'md_verified'`; a table with a garbled displayed cell stays
 * `imported_unverified` (amendment F). Verified by
 * `scripts/regulation-tables/verify-regulation-tables.ts iso14046 "<transcript>"`.
 * Emitted as `20260917102600_regulation_tables_seed_iso14046.sql` (no earlier
 * ISO-14046 table seed exists — nothing superseded).
 *
 * Edition: the title page prints "esta norma es una adopción idéntica (IDT) por
 * traducción de la norma ISO 14046:2014." (L13–L15); prod `standards.version` is
 * "ISO 14046:2014" (read-only 2026-09-18) → token `'2014'`.
 *
 * The standard prints NO numeric value table (inventory §1 confirmed in-session:
 * `grep -n "Tabla\|Table\|Tabelle"` → no hit, exit 1 — report §3). Its two
 * catalogues are TEXT lists the worksheets turn into checklists:
 *   - S5_2_4_2_DQ — the ten data-quality items a) – j) of §5.2.4.2 (L595–L605).
 *     NOTE: the brief names this list "§5.2.2 a)–j)"; the transcript prints it under
 *     5.2.4.2 "Calidad de los datos" (§5.2.2 is the scope list a) – p) L521–L538) —
 *     the table code follows the printed clause (iso14046-J-4). Policy `anhaltswert`:
 *     the lead-in prints the conditional "deberían tratar" (L595), never "deben".
 *   - S6_2_TP — the seven third-party-report aspects a) – g) of §6.2 (L909–L984),
 *     each with its printed heading and its printed sub-items 1) … / i) …. Policy
 *     `locked`: "El informe de tercera parte debe cubrir los siguientes aspectos:"
 *     (L909). The transcript prints OCR quirks INSIDE the sub-items ("Ias" L916 /
 *     L973, "ii)cualquier" L923, "$y$" L926, "iii)resultado" L927, the duplicated
 *     L940 / L941 line) — kept verbatim, table `imported_unverified`, iso14046-U-1.
 */
import type { RegulationTable, RegulationRow } from './regulation-tables';
import { Q } from './regulation-tables-quotes-iso14046';

const STD = 'ISO-14046';
export const ISO14046_EDITION = '2014';
const ED = ISO14046_EDITION;

const collapse = (s: string) => s.replace(/\s+/g, ' ').trim();
/** Build-time SR-1 guard: every seeded cell text must be printed inside the named span (whitespace-collapsed). */
function inSpan(quote: string, cell: string | null, where: string): void {
  if (cell !== null && !collapse(quote).includes(collapse(cell))) throw new Error(`${where}: cell "${cell}" is not inside its verbatim span`);
}
/** The printed item text without its "x)" marker (whitespace-collapsed); the span must start with that marker. */
export function itemText(item: string, quote: string): string {
  const m = collapse(quote).match(/^([a-j])\)\s+(.*)$/);
  if (!m || m[1] !== item) throw new Error(`item ${item}: span does not start with "${item})"`);
  return m[2];
}

// ---------------------------------------------------------------------------
// S5_2_4_2_DQ — §5.2.4.2 (L595–L605): "Los requisitos para la calidad de los datos deberían tratar lo siguiente:"
// a) – j). One row per printed item; `letter` the printed marker, `text` the item without it. Keys = the item
// letters; the created `data_quality_items` select_many (-02 F) offers the printed lines (`label_de`) as its
// options (the checklist renders enum_values[].value — m820_2 trap 1). Policy anhaltswert ("deberían").
// ---------------------------------------------------------------------------
export const S5_2_4_2_DQ_ROWS = [
  { item: 'a', quote: Q.L596 }, { item: 'b', quote: Q.L597 }, { item: 'c', quote: Q.L598 }, { item: 'd', quote: Q.L599 }, { item: 'e', quote: Q.L600 },
  { item: 'f', quote: Q.L601 }, { item: 'g', quote: Q.L602 }, { item: 'h', quote: Q.L603 }, { item: 'i', quote: Q.L604 }, { item: 'j', quote: Q.L605 },
] as const;
export function s5242DqAsTable(): RegulationTable {
  inSpan(Q.L595, 'deberían tratar lo siguiente', 'S5_2_4_2_DQ policy');
  const rows: RegulationRow[] = S5_2_4_2_DQ_ROWS.map((r, i) => {
    const text = itemText(r.item, r.quote);
    inSpan(r.quote, text, `S5_2_4_2_DQ ${r.item}`);
    return { row_key: r.item, keys: { item: r.item }, group_label: null, label_de: `${r.item}) ${text}`, order_index: i,
      values: { letter: `${r.item})`, text }, verbatim_quote: r.quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'S5_2_4_2_DQ', title_de: 'Anforderungen an die Datenqualität a) – j) (§5.2.4.2 „deberían tratar lo siguiente“)', clause_reference: '§5.2.4.2', page_ref: null,
    key_columns: ['item'],
    value_columns: [{ name: 'letter', type: 'string' }, { name: 'text', type: 'string' }],
    override_policy: 'anhaltswert',
    override_quote: Q.L595,
    verification_status: 'md_verified', rows };
}

// ---------------------------------------------------------------------------
// S6_2_TP — §6.2 (L909–L984): "El informe de tercera parte debe cubrir los siguientes aspectos:" a) – g). One row per
// printed aspect; `letter` the printed marker, `heading` the printed heading text after it (first line of the span),
// `subitems` the printed sub-items 1) … / i) … joined (the remaining lines, verbatim incl. OCR quirks — U-1). Keys =
// the letters; the created `third_party_report_items` select_many (-06 C) offers "x) heading" as its options.
// Policy locked ("debe cubrir"). Status imported_unverified (garbled displayed sub-item cells, amendment F).
// ---------------------------------------------------------------------------
export const S6_2_TP_ROWS = [
  { item: 'a', quote: Q.L910_913 }, { item: 'b', quote: Q.L914_919 }, { item: 'c', quote: Q.L920_941 }, { item: 'd', quote: Q.L942_955 },
  { item: 'e', quote: Q.L956_971 }, { item: 'f', quote: Q.L972_978 }, { item: 'g', quote: Q.L981_984 },
] as const;
/** The printed OCR quirks inside the S6_2_TP sub-items, asserted present so a silent "correction" cannot slip in (iso14046-U-1). */
export const S6_2_TP_OCR_QUIRKS: ReadonlyArray<{ item: string; printed: string }> = [
  { item: 'b', printed: 'Ias aplicaciones previstas' },
  { item: 'c', printed: 'ii)cualquier omisión' },
  { item: 'c', printed: 'ii) definición; $y$' },
  { item: 'c', printed: 'iii)resultado de la medición' },
  { item: 'c', printed: 'justificación de cualquier modificación hecha al alcance inicial-' },
  { item: 'f', printed: 'Ios resultados' },
];
export function s62TpAsTable(): RegulationTable {
  inSpan(Q.L909, 'debe cubrir los siguientes aspectos', 'S6_2_TP policy');
  const rows: RegulationRow[] = S6_2_TP_ROWS.map((r, i) => {
    const lines = r.quote.split('\n');
    const heading = itemText(r.item, lines[0]);
    const subitems = collapse(lines.slice(1).join(' '));
    if (!subitems.length) throw new Error(`S6_2_TP ${r.item}: no sub-items in the span`);
    inSpan(r.quote, heading, `S6_2_TP ${r.item} heading`);
    inSpan(r.quote, subitems, `S6_2_TP ${r.item} subitems`);
    for (const q of S6_2_TP_OCR_QUIRKS.filter((x) => x.item === r.item)) inSpan(r.quote, q.printed, `S6_2_TP ${r.item} OCR quirk`);
    return { row_key: r.item, keys: { item: r.item }, group_label: null, label_de: `${r.item}) ${heading}`, order_index: i,
      values: { letter: `${r.item})`, heading, subitems }, verbatim_quote: r.quote };
  });
  return { standard_code: STD, edition: ED, table_code: 'S6_2_TP', title_de: 'Inhalte des Berichts an Dritte a) – g) (§6.2 „debe cubrir los siguientes aspectos“)', clause_reference: '§6.2', page_ref: null,
    key_columns: ['item'],
    value_columns: [{ name: 'letter', type: 'string' }, { name: 'heading', type: 'string' }, { name: 'subitems', type: 'string' }],
    override_policy: 'locked',
    override_quote: Q.L909,
    verification_status: 'imported_unverified', rows };
}

/** The live ISO-14046 set (two text catalogues). */
export function iso14046SeedTables(): RegulationTable[] {
  return [s5242DqAsTable(), s62TpAsTable()];
}
